"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type BadgeProps = Omit<React.ComponentProps<"span">, "onClick"> & {
  /**
   * default, ink and accent are pills. series drops the pill: sibling tags are
   * written as one list ("Identity, Web and Motion"), in the italic, and the
   * commas and the "and" re-set as tags come and go. seal sets `legend` round
   * a ring, like a coin, with the children in the middle.
   */
  variant?: "default" | "ink" | "accent" | "series" | "seal"
  /**
   * Makes the tag removable: the whole pill becomes a button with a cross, and
   * pointing at it strikes the word. It closes up, then this is called.
   * Focus moves to the neighbouring tag. Not for seal.
   */
  onRemove?: () => void
  /** seal: the words set round the rim, about 12 to 24 characters. */
  legend?: string
}

/** The one rounded shape: a hairline pill. */
function Badge({ className, variant = "default", onRemove, legend, children, ...props }: BadgeProps) {
  const id = React.useId()
  const dataVariant = variant === "default" ? undefined : variant

  if (variant === "seal") {
    const name = props["aria-label"] ?? [typeof children === "string" ? children : "", legend].filter(Boolean).join(", ")
    return (
      <span data-slot="badge" data-variant="seal" role="img" className={cn("db-tag", className)} {...props} aria-label={name}>
        <svg viewBox="0 0 90 90" aria-hidden="true">
          <circle className="db-tag-rim" cx="45" cy="45" r="44.5" />
          <circle className="db-tag-rim" cx="45" cy="45" r="28.5" />
          {/* From the foot, round by the left: the legend reads clockwise over the top, as on a coin. */}
          <path id={id} d="M45 77a32 32 0 1 1 0-64a32 32 0 1 1 0 64" fill="none" />
          <text className="db-tag-legend">
            <textPath href={`#${id}`} textLength={2 * Math.PI * 32} lengthAdjust="spacing">{`${legend ?? ""} · `}</textPath>
          </text>
        </svg>
        <span className="db-tag-face" aria-hidden="true">{children}</span>
      </span>
    )
  }

  if (!onRemove) {
    return (
      <span data-slot="badge" data-variant={dataVariant} className={cn("db-tag", className)} {...props}>
        {children}
      </span>
    )
  }

  const { "aria-label": label, ...rest } = props
  const remove = (e: React.MouseEvent<HTMLButtonElement>) => {
    const tag = e.currentTarget
    if (tag.hasAttribute("data-leaving")) return
    const next = tag.nextElementSibling ?? tag.previousElementSibling
    const done = () => {
      if (next instanceof HTMLButtonElement) next.focus()
      onRemove()
    }
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return done()
    // Struck through, the tag closes up and its neighbours slide into the space.
    tag.setAttribute("data-leaving", "")
    tag.style.overflow = "clip"
    const gap = parseFloat(getComputedStyle(tag.parentElement ?? tag).columnGap) || 0
    tag
      .animate(
        [
          { width: `${tag.offsetWidth}px`, opacity: 1 },
          { width: "0px", paddingInline: "0px", marginInlineEnd: `${-gap}px`, opacity: 0 },
        ],
        { duration: 480, easing: "cubic-bezier(.65,0,.35,1)", fill: "forwards" },
      )
      .finished.then(done)
  }

  return (
    <button
      type="button"
      data-slot="badge"
      data-variant={dataVariant}
      data-removable=""
      aria-label={label ?? (typeof children === "string" ? `Remove ${children}` : "Remove")}
      className={cn("db-tag", className)}
      onClick={remove}
      {...(rest as React.ComponentProps<"button">)}
    >
      <span>{children}</span>
    </button>
  )
}

export { Badge, type BadgeProps }

@layer components {
  /* ── db-tag ── the one rounded shape. The word is set as Weingart set his callouts: small, a little heavy and narrow, so it holds as type. */
  .db-tag {
    display: inline-flex; align-items: baseline; gap: 0.45em;
    margin: 0; border: 0; padding: 0.22em 0.8em 0.26em; border-radius: 999px;
    background: none; box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong);
    font-family: var(--db-voice); font-size: var(--db-pp); line-height: 1.3; font-weight: 500; font-stretch: 92%; letter-spacing: 0.01em;
    color: var(--db-ink); white-space: nowrap;
  }
  .db-tag[data-variant="ink"] { background: var(--db-ink); color: var(--db-paper); box-shadow: none; font-weight: 650; font-stretch: 88%; }
  .db-tag[data-variant="accent"] { color: var(--db-accent); box-shadow: inset 0 0 0 var(--db-hairline) currentColor; }
  button.db-tag { cursor: pointer; transition: box-shadow var(--db-allegro), color var(--db-allegro); }
  button.db-tag[data-removable]::after { content: "×" / ""; opacity: 0.5; transition: opacity var(--db-allegro); }
  button.db-tag:is(:hover, [data-force~="hover"]) { color: var(--db-ink); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-ink); }
  button.db-tag:is(:hover, [data-force~="hover"])::after { opacity: 1; }
  button.db-tag[data-removable] > span {
    background: linear-gradient(currentColor, currentColor) no-repeat 100% 58% / 0% var(--db-hairline);
    transition: background-size var(--db-moderato) var(--db-breath), background-position 0s;
  }
  button.db-tag[data-removable]:is(:hover, :focus-visible, [data-force~="hover"]) > span { background-position: 0 58%; background-size: 100% var(--db-hairline); }

  /* series: no pill. Sibling tags are one written list, yours in the italic; ours are the commas and the "and", which re-set
     themselves as a tag leaves (a leaving tag no longer counts). --and localises the conjunction. */
  .db-tag[data-variant="series"] {
    --and: "and";
    display: inline-block; padding: 0; border-radius: 0; box-shadow: none; background: none; color: var(--db-ink);
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-stretch: 100%; letter-spacing: 0;
    font-size: calc(var(--db-expression-scale) * 1em); line-height: inherit; vertical-align: baseline;
  }
  button.db-tag[data-variant="series"], button.db-tag[data-variant="series"]:is(:hover, [data-force~="hover"]) { box-shadow: none; color: var(--db-ink); }
  button.db-tag[data-variant="series"] > span { background-position: 100% 62%; }
  button.db-tag[data-variant="series"]:is(:hover, :focus-visible, [data-force~="hover"]) > span { background-position: 0 62%; }
  button.db-tag[data-variant="series"]::after { content: none; }
  :is(span, button).db-tag[data-variant="series"]::after {
    font-family: var(--db-voice); font-style: normal; font-size: calc(1em / var(--db-expression-scale)); color: var(--db-graphite); opacity: 1;
  }
  .db-tag[data-variant="series"]:not(:nth-last-child(1 of .db-tag[data-variant="series"]:not([data-leaving]))) { margin-inline-end: 0.28em; }
  .db-tag[data-variant="series"]:nth-last-child(n + 3 of .db-tag[data-variant="series"]:not([data-leaving]))::after { content: ","; }
  .db-tag[data-variant="series"]:nth-last-child(2 of .db-tag[data-variant="series"]:not([data-leaving]))::after { content: "\a0" var(--and); }

  /* seal: a coin. The legend set round the rim between two hairline rings, the face in the middle; pointing turns the legend a little. */
  .db-tag[data-variant="seal"] {
    position: relative; display: inline-grid; place-items: center; inline-size: var(--db-space-8); block-size: var(--db-space-8); padding: 0;
    box-shadow: none; color: var(--db-ink); vertical-align: middle;
  }
  .db-tag[data-variant="seal"] > svg { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; overflow: visible; }
  .db-tag-rim { fill: none; stroke: var(--db-rule-strong); stroke-width: var(--db-hairline); }
  .db-tag-legend {
    fill: currentColor; font-family: var(--db-voice); font-size: var(--db-pp); font-weight: 550; font-stretch: 100%; text-transform: uppercase;
    transform-origin: 45px 45px; transition: rotate var(--db-andante) var(--db-breath);
  }
  .db-tag[data-variant="seal"]:is(:hover, [data-force~="hover"]) .db-tag-legend { rotate: 30deg; }
  .db-tag-face { font-size: var(--db-mf); line-height: 1; letter-spacing: var(--db-mf-tr); font-weight: 250; font-stretch: 100%; font-variant-numeric: lining-nums; }
  @media (forced-colors: active) {
    .db-tag:not([data-variant="series"], [data-variant="seal"]) { outline: var(--db-hairline) solid CanvasText; outline-offset: calc(-1 * var(--db-hairline)); }
    button.db-tag[data-removable]:is(:hover, :focus-visible, [data-force~="hover"]) > span { text-decoration: line-through; }
  }
  @media (forced-colors: active) { .db-tag-rim { stroke: CanvasText; } .db-tag-legend { fill: CanvasText; } }
}
